theorem switchStarts_edges (p q : GraphPath G) (h : G.Adj p.start q.start)
    (hd : Disjoint p.support q.support) :
    (switchStarts p q h hd).edges = p.edges ∪ q.edges ∪ {s(p.start, q.start)}

theorem switchEnds_edges (p q : GraphPath G) (h : G.Adj p.finish q.finish)
    (hd : Disjoint p.support q.support) :
    (switchEnds p q h hd).edges = p.edges ∪ q.edges ∪ {s(p.finish, q.finish)}

theorem incidentEdges_eq (c : GraphCycle G) {v : V} (hv : v ∈ c.support) :
    c.incidentEdges v =
      {s(v, c.succAt hv), s((c.openAt hv).walk.penultimate, v)}

lemma ProtectedAt.incidentEdges_subset_cycle {p : GraphPath G}
