    (ha : a ∈ U) (hb : b ∈ U) (hadj : G.Adj a b) :
    (edgeSingletonsCover (G := G) ha hb hadj).card = U.card - 1

lemma pathCoverNumber_le_card_sub_one_of_adj {U : Finset V} {a b : V}
    (ha : a ∈ U) (hb : b ∈ U) (hadj : G.Adj a b) :
    pathCoverNumber G U ≤ U.card - 1

lemma not_adj_of_pathCoverNumber_eq_card {U : Finset V}
    (h : pathCoverNumber G U = U.card) {a b : V}
    (ha : a ∈ U) (hb : b ∈ U) : ¬ G.Adj a b

lemma ineligibleSet_eq_empty_of_pathCoverNumber_eq_card {U : Finset V}
    (h : pathCoverNumber G U = U.card) :
    ineligibleSet G U = ∅

lemma mem_rootChild_iff {U : Finset V} {x : V}
    {C : (complInduce (G := G) U).ConnectedComponent} :
    x ∈ rootChild (G := G) U C ↔ ∃ hx : x ∈ U, rootComp (G := G) U hx = C

lemma disjoint_rootChild {U : Finset V}
    {C D : (complInduce (G := G) U).ConnectedComponent} (hCD : C ≠ D) :
    Disjoint (rootChild (G := G) U C) (rootChild (G := G) U D)

lemma adj_of_mem_distinct_rootChild {U : Finset V}
    {C D : (complInduce (G := G) U).ConnectedComponent} (hCD : C ≠ D)
    {x y : V}
    (hx : x ∈ rootChild (G := G) U C)
    (hy : y ∈ rootChild (G := G) U D) :
    G.Adj x y

lemma adj_mem_rootChild_not_mem {U : Finset V}
    {C : (complInduce (G := G) U).ConnectedComponent} {x y : V}
    (hx : x ∈ rootChild (G := G) U C) (hy : y ∈ U)
    (hyC : y ∉ rootChild (G := G) U C) : G.Adj x y

lemma union_erase_eq_erase {U A B : Finset V} {x : V}
    (hunion : A ∪ B = U) (hxA : x ∈ A) (hxB : x ∉ B) :
    B ∪ A.erase x = U.erase x

lemma NoConsecutive_of_edges_subset {B : Finset V} {p q : GraphPath G}
    (hsub : q.edges ⊆ p.edges) (hno : NoConsecutive B p) :
    NoConsecutive B q

lemma snd_not_mem_of_NoConsecutive {B : Finset V} {p : GraphPath G}
    (h : ¬ p.walk.Nil) (hs : p.start ∈ B) (hno : NoConsecutive B p) :
    p.walk.snd ∉ B

lemma edges_concatAdj {x : V} (p : GraphPath G) (h : G.Adj p.finish x)
    (hx : x ∉ p.support) :
    (p.concatAdj h hx).edges = p.edges ∪ {s(p.finish, x)}

lemma edges_consAdj {x : V} (p : GraphPath G) (h : G.Adj x p.start)
    (hx : x ∉ p.support) :
    (p.consAdj h hx).edges = p.edges ∪ {s(x, p.start)}

lemma edges_splice (p q : GraphPath G) (h : G.Adj p.finish q.start)
    (hd : Disjoint p.support q.support) :
    (p.splice q h hd).edges = p.edges ∪ q.edges ∪ {s(p.finish, q.start)}
